CREATE FUNCTION pg_temp.require_true(value boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label;END IF;END $$;
CREATE FUNCTION pg_temp.require_denied(command text,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE command;EXCEPTION WHEN insufficient_privilege THEN RETURN;END;RAISE EXCEPTION 'FAIL: %',label;END $$;
CREATE FUNCTION pg_temp.require_platform_denied(command text,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE command;EXCEPTION WHEN raise_exception THEN IF SQLERRM='Unauthorized' THEN RETURN;END IF;RAISE;END;RAISE EXCEPTION 'FAIL: %',label;END $$;
